import{z as l,x as o,o as e,c as s,q as t,j as n,D as E,d as r,s as B,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"场内对冲场外暴露","description":"","frontmatter":{"title":"场内对冲场外暴露","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ot-exchange-hedge-otc.md","filePath":"quant/ot-exchange-hedge-otc.md","lastUpdated":1791413859000}'),d={name:"quant/ot-exchange-hedge-otc.md"};function h(p,a,u,c,C,m){const A=o("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="场内对冲场外暴露" tabindex="-1">场内对冲场外暴露 <a class="header-anchor" href="#场内对冲场外暴露" aria-label="Permalink to &quot;场内对冲场外暴露&quot;">​</a></h1><div class="epigraph"><p>场外条款是连续的，场内工具是离散的：对冲完成后账上剩下的不是零，是三类有名有姓的残差——基差、曲面与缺口。</p><footer>—— 据 Almgren and Chriss, Journal of Risk, 2000 与场外做市执行实务整理</footer></div><p><a href="/quant/ot-counterparty-credit">上一课</a>把对手信用折进价格。回到发行台的执行层：场外负债的对冲工具大多只能在场内找——股指期货、ETF、场内期权、国债期货。本课写三条失配怎么落账：条款连续与工具离散的价格失配、场外参数与场内曲面的波动率失配、条款时钟与市场微观结构的流动性失配。发行方的负债分解沿<a href="/quant/ot-issuer-hedging">发行方视角</a>，本课补齐工具那一列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>雪球敲入线 \\(73\\%\\)，场内期权最深的实值行权价未必够到；FCN 的保护垫要放到三年，场内期权到期最长的月份屈指可数；对冲需要的是每天按时段的增量流量，场内流动性集中在开盘、收盘与竞价。对冲后的账本不是「已对冲」，而是换成了一套残差：用期货替 delta，把现货与期货的基差换进来；用最接近的行权价条带替 vega，把曲面插值差换进来；用日内计划替连续复制，把涨跌停与跳空换进来。缺口的本质是承认：对冲是换暴露，不是消暴露。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条失配各给一条工法。基差：delta 用期货执行时，展期成本与基差波动单列一个桶，对冲需求的季节性会推高贴水——中国市场上中证 500 股指期货的年化对冲成本在部分年份达到两位数百分比，据公开基差数据整理；口径沿<a href="/quant/cn-stockindex-basis">股指期货与贴水</a>。曲面：场外参数（障碍带、期限）落在场内报价的凸包之外时，用<a href="/quant/vanna-volga">vanna / volga</a> 三点或局部插值外推，插值假设与外推幅度写进残差桶，不写成对冲成本。流动性与缺口：执行计划按<a href="/quant/almgren-chriss">平方根与 Almgren–Chriss</a> 的时间尺度排程，用<a href="/quant/adaptive-pov">自适应参与率</a>贴市况；涨跌停与集合竞价的不可成交时段沿<a href="/quant/cn-limit-auction">涨跌停与集合竞价</a>单列情景，隔夜跳空沿<a href="/quant/overnight-gap-hedge">隔夜跳空对冲</a>的两列报告。</p><p><span class="marginnote">术语翻译：基差就是期货价与现货价的差；贴水指期货长期比现货便宜。用期货替现货做对冲，每次展期都在低价位卖旧买新，成本年化下来能吃掉好几个百分点——「对冲了」和「免费对冲了」是两回事。</span></p>',8)),(e(),n(i,null,{default:E(()=>[B(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OTC%5B%22%E5%9C%BA%E5%A4%96%E8%B4%9F%E5%80%BA%EF%BC%9A%E8%BF%9E%E7%BB%AD%E6%9D%A1%E6%AC%BE%22%5D%20--%3E%20EX%5B%22%E5%9C%BA%E5%86%85%E5%B7%A5%E5%85%B7%EF%BC%9A%E6%9C%9F%E8%B4%A7%E3%80%81ETF%E3%80%81%E6%9C%9F%E6%9D%83%22%5D%0A%20%20EX%20--%3E%20R1%5B%22%E5%9F%BA%E5%B7%AE%E6%A1%B6%EF%BC%9A%E5%B1%95%E6%9C%9F%E4%B8%8E%E8%B4%B4%E6%B0%B4%22%5D%0A%20%20EX%20--%3E%20R2%5B%22%E6%9B%B2%E9%9D%A2%E6%A1%B6%EF%BC%9A%E6%8F%92%E5%80%BC%E4%B8%8E%E5%A4%96%E6%8E%A8%22%5D%0A%20%20EX%20--%3E%20R3%5B%22%E7%BC%BA%E5%8F%A3%E6%A1%B6%EF%BC%9A%E8%B7%B3%E7%A9%BA%E4%B8%8E%E6%B6%A8%E8%B7%8C%E5%81%9C%22%5D%0A%20%20PLAN%5B%22%E6%89%A7%E8%A1%8C%E8%AE%A1%E5%88%92%EF%BC%9A%E6%97%B6%E9%97%B4%E5%B0%BA%E5%BA%A6%E4%B8%8E%E5%8F%82%E4%B8%8E%E7%8E%87%22%5D%20--%3E%20EX%0A%20%20R1%20--%3E%20LIM%5B%22%E6%AE%8B%E5%B7%AE%E9%99%90%E9%A2%9D%EF%BC%9A%E6%AF%8F%E6%A1%B6%E4%B8%80%E6%9D%A1%22%5D%0A%20%20R2%20--%3E%20LIM%0A%20%20R3%20--%3E%20LIM%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制上，残差必须分桶认领，因为三类的对冲工具不同：基差桶用展期管理与现货替换，曲面桶用场外互惠与减仓管理，缺口桶用静态条带与现金垫管理。混桶的代价是归因失效：<a href="/quant/ot-issuer-hedging">发行方视角</a>的日度归因里，残差桶如果混着基差与缺口，利差交易与事件风险互相掩护，谁都调不准。对冲纪律优先于工具选择：同样的场内工具，频率与观察网格对齐的账本，残差显著小于均匀加密的账本——<a href="/quant/delta-hedge-freq">离散对冲频率</a>立的口径在执行层兑现。不这么做会错在哪：把「已用期货对冲」当成零风险，市场冲击来临时基差、贴水与折价同时动，账本的三只残差桶一起膨胀，而限额以为只有一条线。</p><p><span class="marginnote">场内对冲的执行成本要按「流量对深度」计，不按佣金计：同样的名义，观察日前的 gamma 峰值时段执行，滑点可以是平静时段的数倍。执行计划因此要挂在观察日历上，而不是挂在固定时点上。</span></p><p><span class="marginnote">常见误区：把「已用期货对冲」当成零风险。期货只换了 delta，基差、贴水、折价一样会亏——市场冲击来临时三只残差桶一起膨胀，若限额只盯一条 delta 线，真实风险早就从报表上「消失」了。</span></p><p><span class="marginnote">数字实例：账本 1 亿名义，隔夜跳空按 ±3% 情景设现金垫，就是 300 万流动性垫。跳空真来 2% 时垫子够用；来 5% 时缺口桶超限——超限不是操作事故，是这桶本来就该报警的地方，报警说明情景库该扩了。</span></p>',5)),(e(),n(i,null,{default:E(()=>[B(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E8%A7%82%E5%AF%9F%E6%97%A5%E5%8E%86%E9%A9%B1%E5%8A%A8%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20P1%5B%22T-1%EF%BC%9A%E9%A2%84%E4%BC%B0%E5%A2%9E%E9%87%8F%E6%B5%81%E9%87%8F%E5%B9%B6%E6%8E%92%E7%A8%8B%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E5%BC%80%E7%9B%98%E6%94%B6%E7%9B%98%E6%B5%81%E5%8A%A8%E6%80%A7%E7%AA%97%E5%8F%A3%E5%88%86%E6%89%B9%E6%89%A7%E8%A1%8C%22%5D%0A%20%20P2%20--%3E%20Q%7B%22%E8%A7%82%E5%AF%9F%E6%97%A5%E6%98%AF%E5%90%A6%E6%95%B2%E5%85%A5%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20N1%5B%22delta%E7%BC%93%E5%8F%98%20%E6%8C%89%E8%AE%A1%E5%88%92%E6%BB%9A%E5%8A%A8%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20N2%5B%22delta%E8%B7%B3%E5%8F%98%20%E7%AB%8B%E5%8D%B3%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20N2%20--%3E%20R%5B%22%E7%BC%BA%E5%8F%A3%E4%B8%8E%E5%9F%BA%E5%B7%AE%E6%A1%B6%E5%90%8C%E6%97%B6%E8%86%A8%E8%83%80%22%5D%0A%20%20R%20--%3E%20L%5B%22%E5%AF%B9%E7%85%A7%E6%AE%8B%E5%B7%AE%E9%99%90%E9%A2%9D%E9%80%90%E6%A1%B6%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只写发行台自己的残差账；市场层面同步对冲对价格的反馈沿<a href="/quant/snowball-dealer-hedging">对冲商的堆积</a>。用场外互惠替代场内工具会引入新的对手信用，缓释口径沿<a href="/quant/ot-counterparty-credit">对手方信用管理</a>。组合层面的集中度与监管义务是下一课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对冲是换暴露：期货换进基差，行权价条带换进曲面插值，日内计划换进缺口。</li><li>三类残差分桶认领，各有工具与限额；混桶使归因失效。</li><li>基差成本随对冲需求与季节性波动，年化可达两位数百分比，口径沿贴水课。</li><li>对冲纪律优先于工具选择：频率与观察网格对齐。</li><li>出处：Almgren and Chriss, <em>Journal of Risk</em>, 2000；Leland, <em>JF</em>, 1985；口径沿<a href="/quant/ot-issuer-hedging">发行方视角</a>、<a href="/quant/delta-hedge-freq">离散对冲频率</a>与<a href="/quant/cn-limit-auction">涨跌停与集合竞价</a>。</li></ul>',4))])}const g=l(d,[["render",h]]);export{_ as __pageData,g as default};
